export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const y = u * t - g * t * t / 2;
  const v = u - g * t;
  const H = u * u / (2 * g);
  const F = m * g;
  let st = 'Rising';
  if (t <= 0) st = 'Ready to toss';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t >= T - 1e-9) st = 'Back at launch height';
  else if (t > ta) st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 40, w: 300, h: 360, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 330, y: 40, w: 300, h: 360, title: 'Velocity over time', state: 'v = u - g t' }));
  o.push(sdk.axis('axis.h', { x: 70, y: 380, length: 300, orientation: 'y', min: 0, max: 2.2, ticks: [0, 1, 2], label: 'Height', unit: 'm' }));
  const py = 380 - y / 2.2 * 300 * 0.9;
  const cx = 140;
  o.push(sdk.circle('ball.toss', cx, py, 26));
  o.push(...sdk.vector('vec.v', { x: cx + 25, y: py }, { value: v, direction: 'up' }, { scale: 8, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a', { x: cx - 25, y: py }, { value: -g, direction: 'up' }, { scale: 8, label: 'a', role: 'warning' }));
  o.push(sdk.callout(190, py - 40 < 90 ? 90 : py - 40, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s^2', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const N = 20;
  const pts = [], rest = [];
  for (let i = 0; i <= N; i++) { const s = 1.8 * i / N; pts.push({ x: s, y: sdk.clamp(u - g * s, -5.5, 5.5) }); }
  const tr = [];
  for (let i = 0; i <= 10; i++) { const s = t * i / 10; tr.push({ x: s, y: u - g * s }); }
  const sl = [{ x: sdk.clamp(t - 0.2, 0, 1.8), y: sdk.clamp(v + g * (t - sdk.clamp(t - 0.2, 0, 1.8)), -5.5, 5.5) }, { x: sdk.clamp(t + 0.2, 0, 1.8), y: sdk.clamp(v - g * (sdk.clamp(t + 0.2, 0, 1.8) - t), -5.5, 5.5) }];
  o.push(sdk.plot('plot.vt', { x: 350, y: 70, w: 270, h: 300, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'faint v', kind: 'line', points: pts }, { label: 'v so far', kind: 'line', points: tr.length > 1 ? tr : [{ x: 0, y: u }, { x: 0.001, y: u }] }, { label: 'slope a = -g', kind: 'line', points: sl }] }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: H, height: y, velocity: v, acceleration: -g, force: F } };
}
